def tile(n):
  N=2**n
  for hr in range(N):
    for hc in range(N):
      g=[[0]*N for _ in range(N)]; g[hr][hc]=-1; c=[0]
      def go(r0,c0,s,hr,hc):
        if s==1: return
        h=s//2; c[0]+=1; t=c[0]; holes=[]
        for dr in (0,1):
          for dc in (0,1):
            qr,qc=r0+dr*h,c0+dc*h
            if qr<=hr<qr+h and qc<=hc<qc+h: holes.append((qr,qc,hr,hc))
            else:
              rr,cc=r0+h-1+dr,c0+h-1+dc; g[rr][cc]=t; holes.append((qr,qc,rr,cc))
        for (qr,qc,a,b) in holes: go(qr,qc,h,a,b)
      go(0,0,N,hr,hc)
      cells={}
      for r in range(N):
        for cc in range(N):
          if g[r][cc]>0: cells.setdefault(g[r][cc],[]).append((r,cc))
      assert sum(1 for r in range(N) for cc in range(N) if g[r][cc]==0)==0
      assert len(cells)==(4**n-1)//3
      for v in cells.values():
        assert len(v)==3
        rs={a for a,b in v}; cs={b for a,b in v}
        assert len(rs)==2 and len(cs)==2 and max(rs)-min(rs)==1 and max(cs)-min(cs)==1
for n in range(1,5): tile(n)

