def can(hole):
  g=[[False]*N for _ in range(N)]; g[hole[0]][hole[1]]=True
  def solve():
    for r in range(N):
      for c in range(N):
        if not g[r][c]:
          for sh in shapes:
            cells=[(r+a,c+b) for a,b in sh]
            if all(0<=x<N and 0<=y<N and not g[x][y] for x,y in cells):
              for x,y in cells: g[x][y]=True
              if solve(): return True
              for x,y in cells: g[x][y]=False
          return False
    return True
  return solve()
