def rep(n,b):
  out=[];e=0
  while n:
    d=n%b
    if d: out.append((d,rep(e,b)))
    n//=b;e+=1
  return out
def ev(r,b): return sum(d*b**ev(e,b) for d,e in r)
def seq(n,k):
  s=[n];b=2
  while len(s)<k and n>0:
    n=ev(rep(n,b),b+1)-1; b+=1; s.append(n)
  return s
